function getTheme(dark) {
  return dark
    ? {
        pageBg: "#221A35",
        surface: "#2E2447",
        surfaceAlt: "#3A2C58",
        sidebarBg: "#2A2140",
        navBg: "#221A35f2",
        heading: "#F3ECFA",
        body: "#C3B2DA",
        bodyMuted: "#9C89B8",
        border: `${LILAC}44`,
        inputBg: "#1B1529",
        inputText: "#F3ECFA",
        placeholder: "#7E6C97",
      }
    : {
        pageBg: CREAM,
        surface: "#ffffff",
        surfaceAlt: PEACH_LIGHT,
        sidebarBg: "#FBF1E0",
        navBg: `${CREAM}f2`,
        heading: PLUM,
        body: "#8a7a97",
        bodyMuted: "#a495ac",
        border: `${LILAC}33`,
        inputBg: CREAM,
        inputText: "#4a3d57",
        placeholder: "#b8aac2",
      };
}

