function CartModal({ cart, onClose, onUpdateQty, onRemove, onOrderPlaced, theme }) {
  const [copied, setCopied] = useState(false);
  const [form, setForm] = useState({
    name: "", email: "", phone: "", altPhone: "", instagram: "",
    address: "", city: "", state: "", pincode: "",
  });
  const [status, setStatus] = useState("idle"); // idle | sending | sent | error
  if (!cart) return null;

  const DELIVERY_FEE = 40;
  const subtotal = cart.reduce((sum, i) => sum + i.price * i.qty, 0);
  const total = cart.length > 0 ? subtotal + DELIVERY_FEE : 0;

  const orderItemsText = cart
    .map((i) => `${i.name} × ${i.qty} (₹${i.price} each = ₹${i.price * i.qty})`)
    .join("\n");

  const orderText =
    cart.length === 0
      ? "Your cart is empty."
      : `Hi StickBe!\n\nI'd like to order:\n${orderItemsText}\n\nSubtotal: ₹${subtotal}\nDelivery: ₹${DELIVERY_FEE}\nTotal: ₹${total}\n\nName: ${form.name}\nEmail: ${form.email}\nPhone: ${form.phone}\nAddress: ${form.address}, ${form.city}, ${form.state} - ${form.pincode}\n\nThank you!`;

  const requiredFilled = form.name && form.email && form.phone && form.instagram && form.address && form.city && form.state && form.pincode;

const handleField = (key) => (e) => {
  let value = e.target.value;
  if (key === "name" || key === "city" || key === "state") {
    value = value.replace(/[^a-zA-Z\s]/g, "");
  }
  if (key === "phone" || key === "altPhone") {
    value = value.replace(/[^0-9]/g, "").slice(0, 10);
  }
  if (key === "pincode") {
    value = value.replace(/[^0-9]/g, "").slice(0, 6);
  }
  setForm((f) => ({ ...f, [key]: value }));
};

  const handleCopy = async () => {
    const fullText = `To: ${ORDER_EMAIL}\nSubject: Order from StickBe site\n\n${orderText}`;
    try {
      await navigator.clipboard.writeText(fullText);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (e) {
      const textarea = document.createElement("textarea");
      textarea.value = fullText;
      document.body.appendChild(textarea);
      textarea.select();
      try { document.execCommand("copy"); setCopied(true); setTimeout(() => setCopied(false), 2000); } catch (err) {}
      document.body.removeChild(textarea);
    }
  };

  const handlePlaceOrder = async () => {
    if (!requiredFilled || cart.length === 0) return;
    setStatus("sending");
    try {
      if (!window.emailjs) throw new Error("EmailJS not loaded");
      await window.emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, {
        customer_name: form.name,
        customer_email: form.email,
        phone: form.phone,
        alt_phone: form.altPhone || "—",
        instagram_handle: form.instagram || "—",
        address: form.address,
        city: form.city,
        state: form.state,
        pincode: form.pincode,
        order_items: orderItemsText,
        subtotal: subtotal,
        delivery_fee: DELIVERY_FEE,
        total: total,
      });
      setStatus("sent");
      onOrderPlaced();
    } catch (err) {
      setStatus("error");
    }
  };

  if (status === "sent") {
    return (
      <div style={{ position: "fixed", inset: 0, background: "rgba(63,43,87,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50, padding: 20 }}>
        <div style={{ background: theme.surface, borderRadius: 18, maxWidth: 360, width: "100%", padding: "36px 26px", textAlign: "center" }}>
          <div style={{ fontSize: 40, marginBottom: 10 }}>🎀</div>
          <p style={{ fontFamily: "'Baloo 2', sans-serif", color: theme.heading, fontSize: 19, margin: "0 0 8px" }}>
            Thank you for ordering!
          </p>
          <p style={{ color: theme.body, fontSize: 14, margin: "0 0 22px", lineHeight: 1.5 }}>
            We'll contact you soon to confirm your order.
          </p>
          <button onClick={onClose} className="stickbe-order-btn" style={{ justifyContent: "center", width: "100%" }}>
            Close
          </button>
        </div>
      </div>
    );
  }

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, background: "rgba(63,43,87,0.45)",
        display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50, padding: 20,
      }}
    >
      <div onClick={(e) => e.stopPropagation()} style={{ background: theme.surface, borderRadius: 18, maxWidth: 440, width: "100%", maxHeight: "88vh", overflowY: "auto", padding: 22, position: "relative" }}>
        <div className="stickbe-tape" style={{ left: 24, top: -6 }} />
        <p style={{ fontFamily: "'Baloo 2', sans-serif", color: theme.heading, fontSize: 19, margin: "6px 0 16px", display: "flex", alignItems: "center", gap: 8 }}>
          <ShoppingCart size={18} /> Your cart
        </p>

        {cart.length === 0 ? (
          <p style={{ color: theme.bodyMuted, fontSize: 14, textAlign: "center", padding: "20px 0" }}>
            Nothing here yet — go add some cute stationery!
          </p>
        ) : (
          <>
            <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 16 }}>
              {cart.map((i) => (
                <div key={i.name} style={{ display: "flex", alignItems: "center", gap: 10, borderBottom: `1px solid ${theme.border}`, paddingBottom: 10 }}>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontFamily: "'Baloo 2', sans-serif", color: theme.heading, fontSize: 14, margin: 0 }}>{i.name}</p>
                    <p style={{ fontSize: 12, color: theme.bodyMuted, margin: "2px 0 0" }}>₹{i.price} each · {i.categoryLabel}</p>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                    <button onClick={() => onUpdateQty(i.name, i.qty - 1)} className="stickbe-qty-btn" aria-label="Decrease quantity">
                      <Minus size={12} />
                    </button>
                    <span style={{ fontFamily: "'Nunito', sans-serif", fontWeight: 700, fontSize: 13, color: theme.heading, minWidth: 16, textAlign: "center" }}>
                      {i.qty}
                    </span>
                    <button onClick={() => onUpdateQty(i.name, i.qty + 1)} className="stickbe-qty-btn" aria-label="Increase quantity">
                      <Plus size={12} />
                    </button>
                  </div>
                  <button onClick={() => onRemove(i.name)} style={{ background: "none", border: "none", color: "#d68a8a", cursor: "pointer", padding: 4 }} aria-label="Remove item">
                    <Trash2 size={14} />
                  </button>
                </div>
              ))}
            </div>

            <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 18 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ fontFamily: "'Nunito', sans-serif", color: theme.bodyMuted, fontSize: 13 }}>Subtotal</span>
                <span style={{ fontFamily: "'Nunito', sans-serif", color: theme.body, fontSize: 13 }}>₹{subtotal}</span>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ fontFamily: "'Nunito', sans-serif", color: theme.bodyMuted, fontSize: 13 }}>Delivery</span>
                <span style={{ fontFamily: "'Nunito', sans-serif", color: theme.body, fontSize: 13 }}>₹{DELIVERY_FEE}</span>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", paddingTop: 6, borderTop: `1px solid ${theme.border}` }}>
                <span style={{ fontFamily: "'Nunito', sans-serif", fontWeight: 700, color: theme.heading, fontSize: 15 }}>Total</span>
                <span style={{ fontFamily: "'Baloo 2', sans-serif", color: PEACH, fontSize: 19, fontWeight: 600 }}>₹{total}</span>
              </div>
            </div>

            <p style={{ fontFamily: "'Baloo 2', sans-serif", color: theme.heading, fontSize: 14.5, margin: "0 0 10px" }}>
              Delivery details
            </p>
            <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 8 }}>
              <input className="stickbe-input" placeholder="Full name *" value={form.name} onChange={handleField("name")} />
              <input className="stickbe-input" placeholder="Email *" value={form.email} onChange={handleField("email")} />
              <div style={{ display: "flex", gap: 8 }}>
                <input className="stickbe-input" placeholder="Phone number *" value={form.phone} onChange={handleField("phone")} style={{ flex: 1 }} />
                <input className="stickbe-input" placeholder="Alt phone (optional)" value={form.altPhone} onChange={handleField("altPhone")} style={{ flex: 1 }} />
              </div>
              <input className="stickbe-input" placeholder="Instagram handle *" value={form.instagram} onChange={handleField("instagram")} />
              <input className="stickbe-input" placeholder="Address *" value={form.address} onChange={handleField("address")} />
              <div style={{ display: "flex", gap: 8 }}>
                <input className="stickbe-input" placeholder="City *" value={form.city} onChange={handleField("city")} style={{ flex: 1 }} />
                <input className="stickbe-input" placeholder="State *" value={form.state} onChange={handleField("state")} style={{ flex: 1 }} />
                <input className="stickbe-input" placeholder="Pincode *" value={form.pincode} onChange={handleField("pincode")} style={{ flex: 1 }} />
              </div>
            </div>

            {status === "error" && (
              <p style={{ color: "#c15c5c", fontSize: 12.5, margin: "6px 0", fontWeight: 700 }}>
                Couldn't send automatically — use "Copy order text" below and email it manually instead.
              </p>
            )}

            <p style={{ fontSize: 11.5, color: "#b8875f", fontWeight: 700, margin: "0 0 8px", textAlign: "center" }}>
              ⚠️ No COD — prepayment required for all orders
            </p>

            <button
              onClick={handlePlaceOrder}
              disabled={!requiredFilled || status === "sending"}
              className="stickbe-order-btn"
              style={{
                width: "100%", justifyContent: "center", margin: "10px 0 14px", padding: "11px 13px", fontSize: 14,
                opacity: !requiredFilled || status === "sending" ? 0.55 : 1,
                cursor: !requiredFilled || status === "sending" ? "not-allowed" : "pointer",
              }}
            >
              {status === "sending" ? "Sending..." : "Place order"}
            </button>

            <details style={{ marginBottom: 4 }}>
              <summary style={{ fontSize: 12, color: theme.bodyMuted, cursor: "pointer", fontWeight: 700 }}>
                Or copy order details manually
              </summary>
              <pre style={{
                background: theme.surfaceAlt, borderRadius: 10, padding: "10px 12px", fontSize: 12,
                color: theme.inputText, whiteSpace: "pre-wrap", fontFamily: "'Nunito', sans-serif", margin: "8px 0",
              }}>
                {orderText}
              </pre>
              <button onClick={handleCopy} className="stickbe-order-btn" style={{ width: "100%", justifyContent: "center", background: PEACH }}>
                {copied ? "Copied!" : "Copy order text"}
              </button>
            </details>
          </>
        )}

        <button
          onClick={onClose}
          style={{ position: "absolute", top: 12, right: 14, background: "none", border: "none", color: "#c4b6cf", fontSize: 18, cursor: "pointer" }}
          aria-label="Close"
        >
          ×
        </button>
      </div>
    </div>
  );
}

function FeedbackForm({ theme }) {
  const [name, setName] = useState("");
  const handleNameChange = (e) => {
  const value = e.target.value.replace(/[^a-zA-Z\s]/g, "");
  setName(value);
};
  const [contact, setContact] = useState("");
  const [message, setMessage] = useState("");
  const [status, setStatus] = useState("idle"); // idle | sending | sent | error

  const requiredFilled = name && contact && message;

  const handleSubmit = async () => {
    if (!requiredFilled) return;
    setStatus("sending");
    try {
      if (!window.emailjs) throw new Error("EmailJS not loaded");
      await window.emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_FEEDBACK_TEMPLATE_ID, {
        from_name: name,
        from_email: contact,
        message: message,
      });
      setStatus("sent");
      setName("");
      setContact("");
      setMessage("");
    } catch (err) {
      setStatus("error");
    }
  };

  if (status === "sent") {
    return (
      <div style={{ maxWidth: 460, margin: "0 auto", background: theme.surface, borderRadius: 16, padding: 30, textAlign: "center", position: "relative", boxShadow: "0 4px 14px rgba(91,62,127,0.08)" }}>
        <div className="stickbe-tape" style={{ left: 24, top: -6 }} />
        <div style={{ fontSize: 34, marginBottom: 8 }}>💌</div>
        <p style={{ fontFamily: "'Baloo 2', sans-serif", color: theme.heading, fontSize: 17, margin: "0 0 6px" }}>
          Thanks for reaching out!
        </p>
        <p style={{ color: theme.body, fontSize: 13.5, margin: 0 }}>
          We'll get back to you soon.
        </p>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: 460, margin: "0 auto", background: theme.surface, borderRadius: 16, padding: 22, position: "relative", boxShadow: "0 4px 14px rgba(91,62,127,0.08)" }}>
      <div className="stickbe-tape" style={{ left: 24, top: -6 }} />
      <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 8 }}>
        <input className="stickbe-input" placeholder="Your name *" value={name} onChange={handleNameChange} />
        <input className="stickbe-input" placeholder="Email *" value={contact} onChange={(e) => setContact(e.target.value)} />
        <textarea
          className="stickbe-input"
          placeholder="Your feedback or question *"
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          rows={4}
          style={{ resize: "vertical", fontFamily: "'Nunito', sans-serif" }}
        />
      </div>

      {status === "error" && (
        <p style={{ color: "#c15c5c", fontSize: 12.5, margin: "10px 0 0", fontWeight: 700 }}>
          Couldn't send — please try again in a moment.
        </p>
      )}

      <button
        onClick={handleSubmit}
        disabled={!requiredFilled || status === "sending"}
        className="stickbe-order-btn"
        style={{
          width: "100%", justifyContent: "center", marginTop: 12, padding: "10px 13px", fontSize: 14,
          opacity: !requiredFilled || status === "sending" ? 0.55 : 1,
          cursor: !requiredFilled || status === "sending" ? "not-allowed" : "pointer",
        }}
      >
        <Send size={13} strokeWidth={2.5} />
        {status === "sending" ? "Sending..." : "Send feedback"}
      </button>
    </div>
  );
}

